def describe_apex_intelligence_architecture() -> str:
    lines = [
        "TitanAI Apex Intelligence Architecture Era",
        "",
        "This era represents TitanAI becoming a complete autonomous engineering and operations partner that understands why software exists, who uses it, how it makes money, how it should evolve, and how to keep it secure and improving.",
        "",
    ]
    for capability in APEX_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
